def route_tool_call(tool_name, arguments):
    owner = tool_owner_index.get(tool_name)
    if owner is None:
        raise ToolNotFoundError(tool_name)
    client = registry.get(owner)
    return client.call_tool(tool_name, arguments)

class ClientCircuitBreaker:
    def __init__(self, failure_threshold=3):
        self.recent_failures = 0
        self.failure_threshold = failure_threshold
        self.open = False

    def record_failure(self):
        self.recent_failures += 1
        if self.recent_failures >= self.failure_threshold:
            self.open = True

    def record_success(self):
        self.recent_failures = 0
        self.open = False

def call_with_timeout(client, tool_name, arguments, timeout_seconds=30):
    try:
        return client.call_tool(tool_name, arguments, timeout=timeout_seconds)
    except TransportClosedError:
        registry.mark_disconnected(client.server_name)
        return error_result(f"{client.server_name} is unavailable")

